"""Summarize retained rows with the pre-outcome gates; never change a judgment."""
import hashlib,json,statistics
from pathlib import Path
R=Path(__file__).resolve().parent
schedule=json.loads((R/'schedule.json').read_text())['rows'];freeze=json.loads((R/'freeze.json').read_text());baseline=json.loads((R/'baseline-linkage.json').read_text());rows=[]
for s in schedule[:8]:
 p=R/'runs'/s['run_id'];d=json.loads((p/'observation.json').read_text());o=d['observation'];review=json.loads((p/'review.json').read_text());a=json.loads((p/'assessment.json').read_text());a=a.get('assessment',a);access=json.loads((p/'access-review.json').read_text());cost=o['cost'];u=o['provider_usage'];pos=[x for x in d['normal_calls'] if x['category']=='normal_context_retrieval' and x['actual_host_proof_status']=='validated' and x['relationships']['proof_validated_relationship_count']>0];supp=[x for x in review.get('relationship_support',[]) if x['status']=='supported'];strict=all(x['judgment']=='correct' for x in review['fact_judgments']) and not review['material_unsupported_claims'];metrics={'mcp_calls':cost['terminal_mcp_invocations'],'shell_commands':cost['terminal_shell_commands'],'outer_round_trips':cost['outer_round_trips'],'model_visible_output_bytes':cost['model_visible_outer_output_bytes'],'duration_ms':o['outcome']['duration_ms'],'provider_input_tokens':u.get('usage',{}).get('input_tokens'),'provider_output_tokens':u.get('usage',{}).get('output_tokens'),'provider_cached_input_tokens':u.get('usage',{}).get('cached_input_tokens')}
 rows.append({'run_id':s['run_id'],'case_id':s['case_id'],'access_status':access['status'],'scope_deviations':access.get('scope_deviations',[]),'loci_invoked':bool(d['normal_calls']),'strict_correct':strict,'fact_counts':a['judgment_counts'],'positive_full_exact_graph_delivery':bool(pos),'positive_full_exact_relationships':sum(x['relationships']['proof_validated_relationship_count'] for x in pos),'supported_answer':bool(supp),'supported_annotation_count':len(supp),'metrics':metrics,'provider_usage':u,'normal_cost':d['normal_cost'],'flags':{'within_wall_cap':metrics['duration_ms']<=300000,'operations_over_60':metrics['mcp_calls']+metrics['shell_commands']>60,'visible_bytes_over_400000':metrics['model_visible_output_bytes']>400000},'evidence_directory':str(p.relative_to(R))})
comparisons=[]
for b in baseline['comparisons']:
 selected=[x for x in rows if x['case_id']==b['case_id']];assert len(selected)==2;cm={}
 for key in selected[0]['metrics']:
  values=[x['metrics'][key] for x in selected];med=statistics.median(values) if all(x is not None for x in values) else None;bm=b['ordinary_metrics'][key]['median'];ratio=med/bm if med is not None and bm else None;cm[key]={'values':values,'min':min(values),'median':med,'max':max(values),'baseline_median':bm,'ratio':ratio,'within_1_25':ratio is not None and ratio<=1.25,'at_or_below_baseline':ratio is not None and ratio<=1}
 comparisons.append({'case_id':b['case_id'],'post_run_ids':[x['run_id'] for x in selected],'baseline_run_ids':b['ordinary_run_ids'],'metrics':cm})
primary=[json.loads((R/'runs'/s['run_id']/'primary-check.json').read_text()) for s in schedule[8:]]
bb=[x for x in rows if x['case_id'] in ['tool_result_capture_binding_type_identity','browser_cli_immediate_production_entrypoint']]
gates={'all_required_facts':{'required':8,'observed':sum(x['strict_correct'] for x in rows)},'positive_full_exact_graph_delivery':{'required':4,'observed':sum(x['positive_full_exact_graph_delivery'] for x in rows)},'binding_browser_positive_delivery':{'required':3,'observed':sum(x['positive_full_exact_graph_delivery'] for x in bb)},'supported_answers':{'required':2,'observed':sum(x['supported_answer'] for x in rows)},'primary_expected_proof':{'required':2,'observed':sum(x['pass'] for x in primary)}}
for g in gates.values():g['pass']=g['observed']>=g['required']
gates['each_binding_browser_case_positive']={'pass':all(any(x['positive_full_exact_graph_delivery'] for x in bb if x['case_id']==case) for case in {x['case_id'] for x in bb})}
gates['cost']={'pass':all(c['metrics'][k]['within_1_25'] for c in comparisons for k in freeze['gates']['cost_metric_keys']),'failed_case_metrics':[{'case_id':c['case_id'],'metric':k,**c['metrics'][k]} for c in comparisons for k in freeze['gates']['cost_metric_keys'] if not c['metrics'][k]['within_1_25']]}
gates['source_prompt_capture_model']={'status':'fail','access_valid_rows':sum(x['access_status']!='scope_deviation' for x in rows),'required_access_valid_rows':8,'scope_deviations':[{'run_id':x['run_id'],'deviations':x['scope_deviations']} for x in rows if x['scope_deviations']],'all_native_models_and_efforts_match':all(json.loads((R/'runs'/s['run_id']/'observation.json').read_text())['observation']['native_identity']['condition_deviations']==[] for s in schedule[:8]),'all_completed_within_cap':all(x['flags']['within_wall_cap'] for x in rows),'prompt':'Primary attests exact frozen spawn submissions; child NEW_TASK payloads are encrypted, so independent native plaintext prompt hashes are unavailable. Source/access/postflight receipts separately retained.'}
efficient=all(c['metrics'][k]['at_or_below_baseline'] for c in comparisons for k in freeze['gates']['cost_metric_keys']) and any(c['metrics'][k]['ratio']<1 for c in comparisons for k in freeze['gates']['cost_metric_keys'])
out={'schema_version':1,'freeze_sha256':hashlib.sha256((R/'freeze.json').read_bytes()).hexdigest(),'disposition':'negative','ordinary_rows':rows,'comparisons':comparisons,'primary_checks':[{'run_id':x['run_id'],'pass':x['pass'],'evidence':f"runs/{x['run_id']}/primary-check.json"} for x in primary],'gates':gates,'efficiency_claim_supported':efficient,'limits':['Eight selected ordinary attempts, two per case; no population, significance, internal-reliance, graph-only causal or dollar-cost claim.','All attempts/failures retained; no replacement, reminders, skipped rows or threshold changes.','New source counts use unique extents per operation; not compared silently with old source sums.','Primary compaction caused duplicate turn_context records; call-level frozen-helper reconciliation retained, no synthetic primary completion or per-case provider cost.','Private Claude work-repository result remains outside scope.','Source archive bytes unavailable; all638 frozen file identities/no-extra-files checked before/after.','Opaque shell activity and upstream silent logging omissions remain unknown.','Full_exact confirms observable delivery and proof, not task relevance by itself or internal cognition.']}
(R/'results.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'gates':gates,'efficiency':efficient},indent=2))
